<template>
  <div class="d-card reveal" ref="cardRef">
    <div class="d-glow"></div>
    <div class="d-meta">
      <span class="d-ctx">{{ item.context }}</span>
      <span class="d-dot"></span>
      <span class="d-num">{{ String(index + 1).padStart(2, '0') }}</span>
    </div>
    <div class="d-title">{{ item.title }}</div>
    <div class="paar">
      <div class="pi">
        <div class="pk P">{{ t('decisions.labels.problem') }}</div>
        <div class="pv">{{ item.problem }}</div>
      </div>
      <div class="pi">
        <div class="pk A1">{{ t('decisions.labels.analyze') }}</div>
        <div class="pv">{{ item.analyze }}</div>
      </div>
      <div class="pi">
        <div class="pk A2">{{ t('decisions.labels.action') }}</div>
        <div class="pv">{{ item.action }}</div>
      </div>
      <div class="pi">
        <div class="pk R">{{ t('decisions.labels.result') }}</div>
        <div class="pv">{{ item.result }}</div>
      </div>
    </div>
    <div class="vs">
      <span class="vrej">{{ item.rejected }}</span>
      <span class="vsep">{{ t('decisions.labels.vs') }}</span>
      <span class="vchosen">✓ {{ item.chosen }}</span>
    </div>
    <div class="rbadge">▸ {{ item.badge }}</div>
  </div>
</template>

<script setup>
import { ref, onMounted } from 'vue'
import { useI18n } from 'vue-i18n'

// eslint-disable-next-line no-undef
defineProps({ item: Object, index: { type: Number, default: 0 } })

const { t } = useI18n()
const cardRef = ref(null)

onMounted(() => {
  const observer = new IntersectionObserver(
    ([entry]) => {
      if (entry.isIntersecting) {
        entry.target.classList.add('visible')
        observer.unobserve(entry.target)
      }
    },
    { threshold: 0.08 }
  )
  if (cardRef.value) observer.observe(cardRef.value)
})
</script>

<style scoped>
.d-card {
  background: var(--bg2);
  border: 1px solid var(--br);
  border-radius: 8px;
  padding: 32px 36px;
  position: relative;
  overflow: hidden;
  transition: all 0.35s;
  cursor: none;
}

/* Left gradient bar */
.d-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0;
  width: 3px; height: 100%;
  background: linear-gradient(180deg, var(--g) 0%, var(--b) 50%, var(--p) 100%);
  opacity: 0;
  transition: opacity 0.3s;
}

/* Top neon line */
.d-card::after {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--g), transparent);
  opacity: 0;
  transition: opacity 0.3s;
}

.d-card:hover {
  border-color: var(--br2);
  transform: translateX(6px);
  box-shadow: 0 8px 40px rgba(0,0,0,0.4);
}
.d-card:hover::before,
.d-card:hover::after { opacity: 1; }
.d-card:hover .d-glow { opacity: 1; }

/* Radial glow overlay */
.d-glow {
  position: absolute;
  top: -50%; right: -20%;
  width: 300px; height: 300px;
  background: radial-gradient(circle, rgba(0,255,136,0.04) 0%, transparent 70%);
  opacity: 0;
  transition: opacity 0.4s;
  pointer-events: none;
}

.d-meta {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 10px;
  position: relative;
  z-index: 1;
}
.d-ctx {
  font-size: 10px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--a);
}
.d-dot { width: 3px; height: 3px; background: var(--tm); border-radius: 50%; }
.d-num { font-size: 10px; color: var(--tm); }

.d-title {
  font-family: var(--disp);
  font-size: 20px;
  font-weight: 700;
  color: var(--tb);
  margin-bottom: 20px;
  line-height: 1.3;
  position: relative;
  z-index: 1;
}

.paar {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin-bottom: 16px;
  position: relative;
  z-index: 1;
}
.pi {
  background: var(--bg3);
  border: 1px solid var(--br);
  border-radius: 5px;
  padding: 13px 16px;
  transition: border-color 0.2s;
}
.pi:hover { border-color: var(--br2); }

.pk {
  font-size: 10px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  margin-bottom: 7px;
  display: flex;
  align-items: center;
  gap: 7px;
}
.pk::before {
  content: '';
  display: block;
  width: 7px; height: 7px;
  border-radius: 1px;
  flex-shrink: 0;
}
.pk.P  { color: var(--a); } .pk.P::before  { background: var(--a); }
.pk.A1 { color: var(--b); } .pk.A1::before { background: var(--b); }
.pk.A2 { color: var(--g); } .pk.A2::before { background: var(--g); }
.pk.R  { color: var(--p); } .pk.R::before  { background: var(--p); }

.pv { font-size: 12px; color: var(--t); line-height: 1.65; }

.vs {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 14px 0 0;
  flex-wrap: wrap;
  position: relative;
  z-index: 1;
}
.vrej {
  padding: 4px 10px;
  font-size: 12px;
  color: #f87171;
  background: rgba(248,113,113,0.07);
  border: 1px solid rgba(248,113,113,0.18);
  border-radius: 2px;
  text-decoration: line-through;
  opacity: 0.75;
}
.vsep { font-size: 10px; color: var(--tm); letter-spacing: 0.1em; }
.vchosen {
  padding: 4px 10px;
  font-size: 12px;
  color: var(--g);
  background: rgba(0,255,136,0.06);
  border: 1px solid rgba(0,255,136,0.22);
  border-radius: 2px;
}

.rbadge {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  margin-top: 13px;
  padding: 7px 16px;
  font-size: 12px;
  color: var(--g);
  background: rgba(0,255,136,0.04);
  border: 1px solid var(--br2);
  border-radius: 2px;
  position: relative;
  z-index: 1;
}

@media (max-width: 600px) {
  .d-card { padding: 20px 18px; }
  .paar { grid-template-columns: 1fr; }
  .d-card:hover { transform: none; }
}
</style>
