  --g: #00ff88; --gd: #00cc6a;
  --g10: rgba(0,255,136,0.1); --g20: rgba(0,255,136,0.2);
  --a: #ffb347; --b: #38bdf8; --p: #a78bfa; --r: #f472b6;
  --bg: #030608; --bg2: #060c12; --bg3: #0a1220; --bg4: #0d1828;
  --br: rgba(0,255,136,0.12); --br2: rgba(0,255,136,0.28); --br3: rgba(0,255,136,0.5);
  --t: #b0bec5; --tb: #ecf0f1; --tm: #546e7a;
  --mono: 'JetBrains Mono', monospace;
  --disp: 'Syne', sans-serif;
}

html { scroll-behavior: smooth; }

body {
  background: var(--bg);
  color: var(--t);
  font-family: var(--mono);
  font-size: 14px;
  line-height: 1.7;
  overflow-x: hidden;
  cursor: none;
}

/* Vignette */
body::before {
  content: '';
  position: fixed;
  inset: 0;
  background: radial-gradient(ellipse at center, transparent 40%, rgba(0,0,0,0.7) 100%);
  pointer-events: none;
  z-index: 1;
}

/* Scanlines CRT */
body::after {
  content: '';
  position: fixed;
  inset: 0;
  background: repeating-linear-gradient(
    0deg,
    transparent, transparent 3px,
    rgba(0,0,0,0.06) 3px, rgba(0,0,0,0.06) 4px
  );
  pointer-events: none;
  z-index: 1;
}

/* Custom Cursor */
#cursor {
  position: fixed;
  width: 10px; height: 10px;
  background: var(--g);
  border-radius: 50%;
  pointer-events: none;
  z-index: 9999;
  transform: translate(-50%, -50%);
