<template>
  <div class="sec-divider"></div>
  <section id="decisions" class="sec" ref="sectionRef">
    <div class="sec-head">
      <span class="sec-tag">{{ t('decisions.tag') }}</span>
      <h2 class="sec-title">{{ t('decisions.title') }}</h2>
    </div>
    <p class="decision-intro reveal" v-html="introHtml" />

    <!-- Auth Flow Diagram -->
    <div class="auth-flow-wrap reveal">
      <div class="af-label">AUTHENTICATION GATEWAY</div>
      <div class="af-nodes">
        <div class="af-node">
          <div class="af-tag s">Samsung</div>
          <div class="af-name">내부 인증</div>
        </div>
        <div class="af-arrow">
          <div class="af-line-wrap">
            <div class="af-line sp"></div>
            <div class="af-arrowhead sp"></div>
          </div>
          <div class="af-tip">세션 검증</div>
        </div>
        <div class="af-node af-node-hub">
          <div class="af-tag p">Portal</div>
          <div class="af-name">인증 허브</div>
        </div>
        <div class="af-arrow">
          <div class="af-line-wrap">
            <div class="af-line pe"></div>
            <div class="af-arrowhead pe"></div>
          </div>
          <div class="af-tip">토큰 발급</div>
        </div>
        <div class="af-node">
          <div class="af-tag e">Solutions ×4</div>
          <div class="af-name">외부 솔루션</div>
        </div>
      </div>
      <p class="af-caption">Single Entry Point · SSO 신뢰 연계 구조 · 인증 책임 단계별 분리</p>
    </div>

    <DecisionCard
      v-for="(item, i) in items"
      :key="i"
      :item="item"
      :index="i"
    />
  </section>
</template>

<script setup>
import { computed, ref, onMounted } from 'vue'
import { useI18n } from 'vue-i18n'
import DecisionCard from './DecisionCard.vue'

const { t, tm } = useI18n()

const introHtml = computed(() =>
  t('decisions.intro').replace(/\n/g, '<br>')
)
const items = computed(() => tm('decisions.items'))

const sectionRef = ref(null)

onMounted(() => {
  const observer = new IntersectionObserver(
    (entries) => {
      entries.forEach((entry, i) => {
        if (entry.isIntersecting) {
          setTimeout(() => entry.target.classList.add('visible'), i * 120)
          observer.unobserve(entry.target)
        }
      })
    },
    { threshold: 0.08 }
  )
  if (sectionRef.value) {
    sectionRef.value.querySelectorAll('.reveal').forEach(el => observer.observe(el))
  }
})
</script>

<style scoped>
.sec {
  position: relative;
  z-index: 2;
  padding: 80px 52px;
  max-width: 1280px;
  margin: 0 auto;
}
.sec-head { display: flex; align-items: center; gap: 16px; margin-bottom: 56px; }
.sec-tag {
  font-size: 10px;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--g);
  background: var(--g10);
  border: 1px solid var(--br2);
  padding: 5px 14px;
  border-radius: 2px;
  text-shadow: 0 0 12px rgba(0,255,136,0.4);
}
.sec-title {
  font-family: var(--disp);
  font-size: 38px;
  font-weight: 800;
  color: var(--tb);
  letter-spacing: -1.5px;
}
.decision-intro {
  font-size: 13px;
  color: var(--tm);
  max-width: 580px;
  margin-bottom: 48px;
  line-height: 1.9;
}

/* Auth Flow — live animated */
.auth-flow-wrap {
  background: var(--bg2);
  border: 1px solid var(--br);
  border-radius: 8px;
  padding: 36px;
  margin-bottom: 16px;
  position: relative;
  overflow: hidden;
}
.af-label {
  position: absolute;
  top: 16px; right: 20px;
  font-size: 10px;
  letter-spacing: 0.2em;
  color: var(--br2);
  text-transform: uppercase;
}
.af-nodes {
  display: flex;
  align-items: center;
  justify-content: center;
}
.af-node {
  background: var(--bg3);
  border: 1px solid var(--br);
  border-radius: 6px;
  padding: 14px 22px;
  text-align: center;
  min-width: 130px;
  transition: border-color 0.3s;
  flex-shrink: 0;
}
.af-node:hover { border-color: var(--br2); }
.af-node-hub { border-color: var(--br2); }

.af-tag {
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  margin-bottom: 5px;
}
.af-tag.s { color: var(--b); }
.af-tag.p { color: var(--g); }
.af-tag.e { color: var(--p); }
.af-name { font-size: 13px; color: var(--tb); font-weight: 500; }

.af-arrow {
  display: flex;
  flex-direction: column;
  align-items: center;
  flex: 1;
  padding: 0 8px;
  min-width: 90px;
}
.af-line-wrap { display: flex; align-items: center; width: 100%; }
.af-line {
  height: 2px;
  flex: 1;
  border-radius: 1px;
  position: relative;
  overflow: hidden;
  background: var(--bg3);
}
.af-line::after {
  content: '';
  position: absolute;
  top: 0; left: -100%;
  width: 60%; height: 100%;
  border-radius: 1px;
  animation: flowLine 2s linear infinite;
}
.af-line.sp::after { background: linear-gradient(90deg, transparent, var(--b), var(--g)); animation-delay: 0s; }
.af-line.pe::after { background: linear-gradient(90deg, transparent, var(--g), var(--p)); animation-delay: 0.6s; }
@keyframes flowLine { to { left: 150%; } }

.af-arrowhead {
  width: 0; height: 0;
  border-top: 5px solid transparent;
  border-bottom: 5px solid transparent;
  margin-left: -1px;
  flex-shrink: 0;
}
.af-arrowhead.sp { border-left: 8px solid var(--g); }
.af-arrowhead.pe { border-left: 8px solid var(--p); }

.af-tip {
  font-size: 10px;
  color: var(--tm);
  text-align: center;
  margin-top: 6px;
  letter-spacing: 0.06em;
}
.af-caption {
  text-align: center;
  font-size: 11px;
  color: var(--tm);
  margin-top: 24px;
  letter-spacing: 0.08em;
}

@media (max-width: 720px) {
  .sec { padding: 60px 16px; }
  .sec-title { font-size: 24px; }
  .af-nodes { flex-wrap: wrap; gap: 8px; justify-content: center; }
  .af-arrow { min-width: 60px; }
}
</style>
